#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <float.h>

#ifndef WARP_SIZE
#define WARP_SIZE 32
#endif

template <typename T>
__device__ __forceinline__ float to_float_dev(T v) { return (float)v; }
template <>
__device__ __forceinline__ float to_float_dev<c10::Half>(c10::Half v) { return (float)v; }
template <>
__device__ __forceinline__ float to_float_dev<c10::BFloat16>(c10::BFloat16 v) { return (float)v; }

template <typename T>
__device__ __forceinline__ T from_float_dev(float v) { return (T)v; }
template <>
__device__ __forceinline__ c10::Half from_float_dev<c10::Half>(float v) { return c10::Half(v); }
template <>
__device__ __forceinline__ c10::BFloat16 from_float_dev<c10::BFloat16>(float v) { return c10::BFloat16(v); }

__device__ __forceinline__ void online_combine(float &m, float &s, float m2, float s2) {
    if (m2 > m) {
        s = s * __expf(m - m2) + s2;
        m = m2;
    } else {
        s = s + s2 * __expf(m2 - m);
    }
}

// one warp per row for modest D; multiple warps per CTA process consecutive rows
template <typename scalar_t, int WARPS_PER_BLOCK>
__global__ __launch_bounds__(WARPS_PER_BLOCK*32, 4)
void softmax_warp_kernel(const scalar_t* __restrict__ x, scalar_t* __restrict__ y, int N, int D) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp = tid >> 5;
    int row = blockIdx.x * WARPS_PER_BLOCK + warp;
    if (row >= N) return;

    const scalar_t* row_x = x + (long long)row * D;
    scalar_t* row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    float s = 0.0f;
    for (int col = lane; col < D; col += 32) {
        float v = to_float_dev<scalar_t>(row_x[col]);
        if (v > m) {
            s *= __expf(m - v);
            m = v;
        }
        s += __expf(v - m);
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        float pm = __shfl_xor_sync(0xffffffff, m, off);
        float ps = __shfl_xor_sync(0xffffffff, s, off);
        online_combine(m, s, pm, ps);
    }
    float inv_s = 1.0f / s;
    for (int col = lane; col < D; col += 32) {
        float v = to_float_dev<scalar_t>(row_x[col]);
        row_y[col] = from_float_dev<scalar_t>(__expf(v - m) * inv_s);
    }
}

// block per row for large D
template <typename scalar_t, int BLOCK>
__global__ __launch_bounds__(BLOCK, 2)
void softmax_block_kernel(const scalar_t* __restrict__ x, scalar_t* __restrict__ y, int N, int D) {
    int row = blockIdx.x;
    if (row >= N) return;
    int tid = threadIdx.x;
    const scalar_t* row_x = x + (long long)row * D;
    scalar_t* row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    float s = 0.0f;
    for (int col = tid; col < D; col += BLOCK) {
        float v = to_float_dev<scalar_t>(row_x[col]);
        if (v > m) {
            s *= __expf(m - v);
            m = v;
        }
        s += __expf(v - m);
    }

    // reduce within warp
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        float pm = __shfl_xor_sync(0xffffffff, m, off);
        float ps = __shfl_xor_sync(0xffffffff, s, off);
        online_combine(m, s, pm, ps);
    }

    __shared__ float smem_m[32];
    __shared__ float smem_s[32];
    int lane = tid & 31;
    int warp = tid >> 5;
    if (lane == 0) { smem_m[warp] = m; smem_s[warp] = s; }
    __syncthreads();

    if (warp == 0) {
        int nwarps = BLOCK / 32;
        m = (lane < nwarps) ? smem_m[lane] : -FLT_MAX;
        s = (lane < nwarps) ? smem_s[lane] : 0.0f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            float pm = __shfl_xor_sync(0xffffffff, m, off);
            float ps = __shfl_xor_sync(0xffffffff, s, off);
            online_combine(m, s, pm, ps);
        }
        if (lane == 0) { smem_m[0] = m; smem_s[0] = s; }
    }
    __syncthreads();
    m = smem_m[0];
    float inv_s = 1.0f / smem_s[0];

    for (int col = tid; col < D; col += BLOCK) {
        float v = to_float_dev<scalar_t>(row_x[col]);
        row_y[col] = from_float_dev<scalar_t>(__expf(v - m) * inv_s);
    }
}

