    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "softmax_forward_h100", [&] {
        const scalar_t* xp = x.data_ptr<scalar_t>();
        scalar_t* yp = y.data_ptr<scalar_t>();
        if (D <= 1024) {
            constexpr int WPB = 4;
            dim3 block(WPB * 32);
            dim3 grid((N + WPB - 1) / WPB);
            softmax_warp_kernel<scalar_t, WPB><<<grid, block, 0, stream>>>(xp, yp, N, D);
        } else {
            constexpr int BLOCK = 256;
            softmax_block_kernel<scalar_t, BLOCK><<<N, BLOCK, 0, stream>>>(xp, yp, N, D);
        }
    });
}
